#!/usr/bin/env python3
"""news-image-20261120 v2 — 'THE WORLD IN ONE PAGE' broadsheet, 1024x1024.
Stdlib only. Renders one PNG from in-file data. Writes ONLY entry.png
into $MAKEFUN_OUTPUT_DIR. Deterministic: no time, no random, no network.
Type is Liberation Serif, rasterised to 1-bit bitmaps in the work dir
and embedded below (see gen_serif.py); no font loading at runtime.
Pins are plotted from lon/lat and asserted inside per-place boxes
(see EXPECTED); fan offsets are capped at 12px on a ~0.97 px/deg map.
"""
import os
import sys
import struct
import zlib
import math

W, H = 1024, 1024

# ---------------------------------------------------------------- palette
# Every colour is named by its role. Gold is decoration only (never text:
# its contrast vs paper is ~2.1:1, below the 4.5:1 body-text floor).
PAPER  = (247, 241, 222)   # paper: cream newsprint
PANEL  = (255, 253, 244)   # panel: lighter paper for cards
INK    = (20, 18, 16)      # ink: near-black body text
MUTED  = (90, 83, 70)      # muted ink: secondary text
RED    = (179, 39, 30)     # red: kicker, rules, DATE CHECK
SEA    = (20, 50, 74)      # sea: dark navy map water
LAND   = (217, 192, 138)   # land: warm beige/tan map land
PINRED = (193, 39, 45)     # pin red: numbered map pins
GOLD   = (201, 162, 39)    # gold: decoration / brief dots (non-text)
RULE   = (138, 127, 102)   # rule: hairlines, dividers
WHITE  = (255, 255, 255)
SLATE  = (74, 96, 110)     # slate: storm sky in scenes
STORM  = (44, 62, 78)      # storm: dark storm shapes
PALE   = (196, 214, 222)   # pale blue-grey: scene sky
SAND2  = (176, 148, 94)    # sand dark: scene ground
FOAM   = (232, 238, 236)   # foam: wave / paper-white scene fill
BROWN  = (150, 90, 40)     # brown: Africa region chip
GREEN  = (60, 110, 70)     # green: Latin America region chip

# ------------------------------------------------------- contrast (WCAG)
def _lin(c):
    c = c / 255.0
    return c / 12.92 if c <= 0.04045 else ((c + 0.055) / 1.055) ** 2.4

def luminance(rgb):
    r, g, b = rgb
    return 0.2126 * _lin(r) + 0.7152 * _lin(g) + 0.0722 * _lin(b)

def contrast(a, b):
    la, lb = luminance(a), luminance(b)
    hi, lo = (la, lb) if la >= lb else (lb, la)
    return (hi + 0.05) / (lo + 0.05)

# (foreground, background, role) — every body-text pair must be >= 4.5:1.
TEXT_PAIRS = [
    (INK, PAPER, "ink on paper (body)"),
    (MUTED, PAPER, "muted ink on paper (secondary)"),
    (RED, PAPER, "red on paper (kicker/labels)"),
    (INK, PANEL, "ink on panel (cards)"),
    (MUTED, PANEL, "muted ink on panel (card decks)"),
    (RED, PANEL, "red on panel (card labels)"),
    (WHITE, INK, "white on ink (count bar)"),
    (WHITE, SEA, "white on sea (map labels)"),
    (INK, LAND, "ink on land (map labels)"),
    (WHITE, PINRED, "white on pin red (pin numbers)"),
    (WHITE, RED, "white on red (chips)"),
    (INK, PALE, "ink on pale scene sky"),
    (WHITE, STORM, "white on storm (lead scene)"),
]

def check_contrast():
    worst = None
    print("CONTRAST MATRIX (unrounded):")
    for fg, bg, role in TEXT_PAIRS:
        r = contrast(fg, bg)
        print("  %-34s %.3f:1" % (role, r))
        assert r >= 4.5, "TEXT PAIR BELOW 4.5:1: %s %.3f" % (role, r)
        if worst is None or r < worst[0]:
            worst = (r, role)
    lm = contrast(LAND, SEA)
    print("  MAP land vs sea luminance ratio: %.3f:1 (need >= 3:1)" % lm)
    print("  land luminance %.4f, sea luminance %.4f" % (luminance(LAND), luminance(SEA)))
    assert lm >= 3.0, "map land/sea contrast below 3:1"
    print("  gold on paper (DECORATION ONLY, never text): %.3f:1" % contrast(GOLD, PAPER))
    print("  worst text pair: %.3f:1 (%s)" % (worst[0], worst[1]))
    return worst, lm

# ------------------------------------------------------------ PNG writer
def write_png(path, w, h, buf):
    # buf: bytes, RGB, w*h*3. No filtering (filter byte 0 per row).
    raw = bytearray()
    stride = w * 3
    for y in range(h):
        raw.append(0)
        raw += buf[y * stride:(y + 1) * stride]
    comp = zlib.compress(bytes(raw), 9)

    def chunk(ctype, data):
        c = struct.pack(">I", len(data)) + ctype + data
        c += struct.pack(">I", zlib.crc32(ctype + data) & 0xFFFFFFFF)
        return c

    ihdr = struct.pack(">IIBBBBB", w, h, 8, 2, 0, 0, 0)
    png = b"\x89PNG\r\n\x1a\n"
    png += chunk(b"IHDR", ihdr)
    png += chunk(b"IDAT", comp)
    png += chunk(b"IEND", b"")
    with open(path, "wb") as f:
        f.write(png)

# ---------------------------------------------------------------- canvas
class CV:
    def __init__(self, w, h, bg):
        self.w, self.h = w, h
        self.buf = bytearray(w * h * 3)
        self.fill(bg)

    def fill(self, c):
        r, g, b = c
        self.buf[0::3] = bytes([r]) * (self.w * self.h)
        self.buf[1::3] = bytes([g]) * (self.w * self.h)
        self.buf[2::3] = bytes([b]) * (self.w * self.h)

    def px(self, x, y, c):
        if 0 <= x < self.w and 0 <= y < self.h:
            i = (y * self.w + x) * 3
            self.buf[i], self.buf[i + 1], self.buf[i + 2] = c

    def rect(self, x, y, w, h, c):
        x0, y0 = max(0, x), max(0, y)
        x1, y1 = min(self.w, x + w), min(self.h, y + h)
        if x1 <= x0 or y1 <= y0:
            return
        r, g, b = c
        row = bytes((r, g, b)) * (x1 - x0)
        for yy in range(y0, y1):
            i = (yy * self.w + x0) * 3
            self.buf[i:i + len(row)] = row

    def hline(self, x, y, w, c, t=1):
        self.rect(x, y, w, t, c)

    def vline(self, x, y, h, c, t=1):
        self.rect(x, y, t, h, c)

    def line(self, x0, y0, x1, y1, c, t=1):
        dx, dy = abs(x1 - x0), abs(y1 - y0)
        sx = 1 if x0 < x1 else -1
        sy = 1 if y0 < y1 else -1
        err = dx - dy
        while True:
            self.rect(x0 - t // 2, y0 - t // 2, t, t, c)
            if x0 == x1 and y0 == y1:
                break
            e2 = 2 * err
            if e2 > -dy:
                err -= dy
                x0 += sx
            if e2 < dx:
                err += dx
                y0 += sy

    def circle(self, cx, cy, r, c, fill=True):
        for yy in range(cy - r, cy + r + 1):
            for xx in range(cx - r, cx + r + 1):
                d = (xx - cx) ** 2 + (yy - cy) ** 2
                if fill:
                    if d <= r * r:
                        self.px(xx, yy, c)
                else:
                    if r * r - r <= d <= r * r:
                        self.px(xx, yy, c)

    def ellipse(self, cx, cy, rx, ry, c, fill=True):
        for yy in range(cy - ry, cy + ry + 1):
            for xx in range(cx - rx, cx + rx + 1):
                v = ((xx - cx) / float(rx)) ** 2 + ((yy - cy) / float(ry)) ** 2
                if fill:
                    if v <= 1.0:
                        self.px(xx, yy, c)
                else:
                    if 0.85 <= v <= 1.0:
                        self.px(xx, yy, c)

    def poly(self, pts, c):
        # scanline fill
        if len(pts) < 3:
            return
        ys = [p[1] for p in pts]
        for y in range(max(0, min(ys)), min(self.h, max(ys) + 1)):
            xs = []
            n = len(pts)
            for i in range(n):
                x0, y0 = pts[i]
                x1, y1 = pts[(i + 1) % n]
                if (y0 <= y < y1) or (y1 <= y < y0):
                    xs.append(x0 + (y - y0) * (x1 - x0) / float(y1 - y0))
            xs.sort()
            for i in range(0, len(xs) - 1, 2):
                self.rect(int(math.ceil(xs[i])), y, int(math.floor(xs[i + 1])) - int(math.ceil(xs[i])) + 1, 1, c)

    def outline(self, x, y, w, h, c, t=1):
        self.rect(x, y, w, t, c)
        self.rect(x, y + h - t, w, t, c)
        self.rect(x, y, t, h, c)
        self.rect(x + w - t, y, t, h, c)

# ------------------------------------------------------- serif fonts
# Glyphs rasterised in the WORK dir only (gen_serif.py) from Liberation
# Serif Regular/Bold via PIL, embedded here as 1-bit bitmaps (SERIF,
# pasted below). The entrypoint renders them with the stdlib-only
# rasteriser below: no PIL, no TTF loading, no network at runtime.
# A glyph is (advance_px, rows) with rows top-aligned to the set's cap
# top; bit (adv-1-col) is the leftmost ink pixel. Cell height h is
# shared by every glyph in the set (cap + descender room), so text
# never needs a per-glyph baseline.
F5 = "F5"
F4 = "F4"
BIG = "BIG"
_SET = {("F4", 1): "S_A", ("F4", 2): "S_B", ("F5", 1): "S_A",
        ("F5", 2): "S_B", ("F5", 3): "S_C",
        ("BIG", 3): "MAST56", ("BIG", 4): "MAST72"}

def _setname(font, scale):
    try:
        return _SET[(font, scale)]
    except KeyError:
        raise AssertionError("no serif set for font %r scale %r" % (font, scale))

def _glyphs(font, scale, bold):
    name = _setname(font, scale)
    d = SERIF[name]
    return d["bold" if bold else "reg"], d["h"]

def _cell(font, scale):
    return SERIF[_setname(font, scale)]["h"]

