def clean(s):
    # Normalise punctuation to glyphs that exist. No '~', no fancy dashes.
    return (s.replace("\u2019", "'").replace("\u2018", "'")
             .replace("\u201c", '"').replace("\u201d", '"')
             .replace("\u2013", "-").replace("\u2014", "-")
             .replace("\u00b7", ".").replace("\u2248", "about ")
             .replace("\u00d7", "x").replace("\u2011", "-"))

def text_w(s, scale, font):
    glyphs, _h = _glyphs(font, scale, False)
    s = clean(s)
    w = 0
    for ch in s:
        g = glyphs.get(ch)
        if g is None:
            raise AssertionError("missing glyph %r" % ch)
        w += g[0]
    return w

def draw_text(cv, x, y, s, scale, color, font=F5, bold=False):
    glyphs, _h = _glyphs(font, scale, bold)
    s = clean(s)
    cx = x
    for ch in s:
        g = glyphs.get(ch)
        if g is None:
            raise AssertionError("missing glyph %r in font" % ch)
        adv, rows = g
        for ry, bits in enumerate(rows):
            col = 0
            while col < adv:
                if (bits >> (adv - 1 - col)) & 1:
                    j = col
                    while j < adv and ((bits >> (adv - 1 - j)) & 1):
                        j += 1
                    cv.rect(cx + col, y + ry, j - col, 1, color)
                    col = j
                else:
                    col += 1
        cx += adv
    return cx

def wrap(s, max_w, scale, font):
    """Word-wrap to lines of measured width <= max_w. Fail loudly if a
    single word cannot fit."""
    s = clean(s)
    words = s.split(" ")
    lines, cur = [], ""
    for w in words:
        trial = (cur + " " + w) if cur else w
        if text_w(trial, scale, font) <= max_w:
            cur = trial
        else:
            if cur:
                lines.append(cur)
            if text_w(w, scale, font) > max_w:
                raise AssertionError("word too wide: %r (%d > %d)" % (w, text_w(w, scale, font), max_w))
            cur = w
    if cur:
        lines.append(cur)
    return lines

def draw_lines(cv, x, y, lines, scale, color, font=F5, pitch=None, bold=False):
    if pitch is None:
        pitch = _cell(font, scale) + 2
    for ln in lines:
        draw_text(cv, x, y, ln, scale, color, font, bold)
        y += pitch
    return y

def chip(cv, x, y, label, scale, fg, bg, font=F4):
    w = text_w(label, scale, font) + 8
    h = _cell(font, scale) + 6
    cv.rect(x, y, w, h, bg)
    draw_text(cv, x + 4, y + 3, label, scale, fg, font, bold=True)
    return w

