def region_counts():
    counts = {r: 0 for r in REGIONS}
    for it in LEADS + TILES:
        counts[it["region"]] += 1
    for (r, _lon, _lat, _t) in BRIEFS:
        counts[r] += 1
    return counts

def check_counts():
    assert len(LEADS) == 3, "leads %d" % len(LEADS)
    assert len(TILES) == 17, "tiles %d" % len(TILES)
    assert len(BRIEFS) == 33, "briefs %d" % len(BRIEFS)
    total = len(LEADS) + len(TILES) + len(BRIEFS)
    assert total >= 53, "total stories %d < 53" % total
    counts = region_counts()
    assert sum(counts.values()) == total, "region sums %d != %d" % (sum(counts.values()), total)
    nums = [t["num"] for t in LEADS + TILES]
    assert nums == list(range(1, 21)), "pin numbers not 1..20: %r" % nums
    print("COUNTS: %d stories = %d leads + %d tiles + %d briefs; 20 pins"
          % (total, len(LEADS), len(TILES), len(BRIEFS)))
    print("REGIONS: " + ", ".join("%s %d" % (r, counts[r]) for r in REGIONS))
    return total, counts

