def point_in_poly(lon, lat, poly):
    inside = False
    n = len(poly)
    for i in range(n):
        x0, y0 = poly[i]
        x1, y1 = poly[(i + 1) % n]
        if (y0 > lat) != (y1 > lat):
            xin = x0 + (lat - y0) * (x1 - x0) / float(y1 - y0)
            if lon < xin:
                inside = not inside
    return inside

def on_land(lon, lat):
    return any(point_in_poly(lon, lat, p) for p in LAND_POLYS)

# Display offsets (px) for crowded pins: the pin disc is drawn offset
# from its true position with a leader line back to a dot on the true
# spot. ROOT CAUSE of the v2 misplacements: the old offsets were up to
# 32px on a map drawn at ~0.97 px per degree, so a "small" fan moved a
# pin by up to 33 DEGREES -- Washington DC landed on the Mexican coast,
# Cincinnati in Hudson Bay. Offsets are now capped at 12px (~12 deg)
# and every disc still sits on land in the right region; the true dot
# (not the disc) marks the city.
