def check_pins():
    for it in LEADS + TILES:
        assert on_land(it["lon"], it["lat"]), \
            "pin %d (%s) not on land: lon %.1f lat %.1f" % (it["num"], it["head"], it["lon"], it["lat"])
        lo0, lo1, la0, la1 = EXPECTED[it["num"]]
        assert lo0 <= it["lon"] <= lo1 and la0 <= it["lat"] <= la1, \
            "pin %d (%s) outside its expected place box: lon %.1f lat %.1f, box lon %.1f..%.1f lat %.1f..%.1f" % (
                it["num"], it["head"], it["lon"], it["lat"], lo0, lo1, la0, la1)
    for num, (dx, dy) in PIN_FAN.items():
        assert abs(dx) <= MAX_FAN_PX and abs(dy) <= MAX_FAN_PX, \
            "pin %d fan offset too large: (%d,%d), cap %dpx" % (num, dx, dy, MAX_FAN_PX)
    for (r, lon, lat, _t) in BRIEFS:
        assert MAP_LON0 <= lon <= MAP_LON1 and MAP_LAT0 <= lat <= MAP_LAT1, \
            "brief dot out of map range: %s %.1f %.1f" % (r, lon, lat)
    print("MAP: all %d pins on-land AND inside their place boxes; fan offsets <= %dpx; all %d brief dots in range"
          % (len(LEADS) + len(TILES), MAX_FAN_PX, len(BRIEFS)))

# ---------------------------------------------------------------- scenes
# Every scene is drawn from concrete shapes (no abstract blobs): a spiral
# storm, a summit table, a market line, a controller, a tower, a tanker,
# a globe, flags, a baseball, a chip, a hippo, a crowd, a courthouse,
# a boat, a city, a ballot box, a shield, a tower, a bat, a clock tower.
def scene(cv, key, x, y, w, h):
    if key == "cyclone":
        cv.rect(x, y, w, h, PALE)
        cv.rect(x, y, w, 6, SLATE)
        for i in range(10):
            rx = x + 6 + i * ((w - 12) // 9)
            cv.line(rx, y + 8, rx - 3, y + 15, SLATE, 1)
        cx, cy = x + int(w * 0.62), y + int(h * 0.52)
        for r in range(max(4, h // 2), 3, -3):
            cv.circle(cx, cy, r, STORM, fill=False)
        cv.circle(cx, cy, 3, RED)
        cv.poly([(x, y + h), (x + w, y + h), (x + w, y + int(h * 0.72)),
                 (x + int(w * 0.55), y + int(h * 0.62)), (x, y + int(h * 0.8))], LAND)
        hx, hy = x + int(w * 0.14), y + int(h * 0.72)
        cv.rect(hx, hy, 12, 8, WHITE)
        cv.poly([(hx - 2, hy), (hx + 6, hy - 6), (hx + 14, hy)], RED)
        cv.line(x, y + h - 3, x + w, y + h - 3, SEA, 2)
        cv.line(x, y + h - 6, x + w, y + h - 6, FOAM, 1)
    elif key == "summit":
        cv.rect(x, y, w, h, PALE)
        # THREE leaders behind the table, distinct robe colours, large heads
        for i, fc in enumerate((RED, SEA, GOLD)):
            hx = x + int(w * (0.22 + 0.28 * i))
            cv.circle(hx, y + int(h * 0.34), 6, FOAM)
            cv.circle(hx, y + int(h * 0.34), 6, INK, fill=False)
            cv.rect(hx - 8, y + int(h * 0.48), 16, 10, fc)
            cv.rect(hx - 8, y + int(h * 0.48), 16, 3, INK)
        cv.ellipse(x + w // 2, y + int(h * 0.78), w // 2 - 4, 8, LAND)
        cv.rect(x + w // 2 - 12, y + int(h * 0.64), 24, 7, WHITE)
        cv.outline(x + w // 2 - 12, y + int(h * 0.64), 24, 7, INK, 1)
        cv.line(x + w // 2 - 9, y + int(h * 0.67), x + w // 2 + 9, y + int(h * 0.67), INK, 1)
        cv.line(x + w // 2 - 9, y + int(h * 0.70), x + w // 2 + 2, y + int(h * 0.70), INK, 1)
    elif key == "market":
        cv.rect(x, y, w, h, PANEL)
        cv.line(x + 6, y + h - 8, x + w - 4, y + h - 8, INK, 1)
        cv.line(x + 6, y + 4, x + 6, y + h - 8, INK, 1)
        # RISING line: $83 (bottom left) to $97.17 (top right), one dip
        pts = [(x + 8, y + h - 12), (x + int(w * 0.3), y + int(h * 0.62)),
               (x + int(w * 0.52), y + int(h * 0.72)),
               (x + int(w * 0.75), y + int(h * 0.38)),
               (x + w - 6, y + int(h * 0.2))]
        for a, b in zip(pts, pts[1:]):
            cv.line(a[0], a[1], b[0], b[1], RED if b[1] > a[1] else GREEN, 2)
        cv.circle(pts[0][0], pts[0][1], 2, INK)
        cv.circle(pts[-1][0], pts[-1][1], 3, GREEN)
        draw_text(cv, x + w - 36, y + 2, "$97.17", 1, GREEN, F4, bold=True)
    elif key == "gta":
        cv.rect(x, y, w, h, PALE)
        cv.circle(x + w - 8, y + 4, 4, GOLD)
        for i, bh in enumerate((8, 13, 10, 14)):
            bx = x + 3 + i * (w // 4)
            cv.rect(bx, y + h - bh - 8, w // 5, bh, SLATE)
            cv.rect(bx + 2, y + h - bh - 5, 2, 2, GOLD)
            cv.rect(bx + 2, y + h - bh - 1, 2, 2, GOLD)
        cy = y + h - 6
        cv.rect(x + w // 2 - 14, cy - 3, 28, 4, RED)
        cv.poly([(x + w // 2 - 8, cy - 3), (x + w // 2 - 4, cy - 7),
                 (x + w // 2 + 6, cy - 7), (x + w // 2 + 10, cy - 3)], RED)
        cv.circle(x + w // 2 - 8, cy + 1, 2, INK)
        cv.circle(x + w // 2 + 8, cy + 1, 2, INK)
        cv.line(x, cy + 3, x + w, cy + 3, INK, 1)
    elif key == "riyadh":
        cv.rect(x, y, w, h, PALE)
        tx = x + w // 2
        cv.poly([(tx - 7, y + h - 2), (tx - 5, y + 2), (tx + 5, y + 2), (tx + 7, y + h - 2)], GOLD)
        cv.poly([(tx - 5, y + 2), (tx + 5, y + 2), (tx, y + 8)], SAND2)
        for wy in (y + 6, y + 10, y + 14):
            cv.line(tx - 4, wy, tx + 4, wy, INK, 1)
        cv.line(x + 4, y + 4, tx - 6, y + 6, RED, 1)
        cv.circle(x + 4, y + 4, 1, RED)
        cv.line(x + w - 4, y + 8, tx + 6, y + 9, RED, 1)
        cv.circle(x + w - 4, y + 8, 1, RED)
        cv.line(x, y + h - 2, x + w, y + h - 2, SAND2, 1)
    elif key == "tanker":
        cv.rect(x, y, w, h, SEA)
        cv.poly([(x + 4, y + h - 10), (x + w - 4, y + h - 10), (x + w - 10, y + h - 2),
                 (x + 10, y + h - 2)], INK)
        cv.rect(x + 8, y + h - 18, 12, 8, RED)
        cv.rect(x + 22, y + h - 18, 12, 8, GOLD)
        cv.poly([(x + w - 12, y + 4), (x + w - 6, y + 12), (x + w - 16, y + 12)], GOLD)
        cv.poly([(x + w - 11, y + 8), (x + w - 7, y + 14), (x + w - 14, y + 14)], RED)
        cv.circle(x + 8, y + 8, 3, INK)
        for a in range(0, 360, 45):
            cv.line(x + 8, y + 8, x + 8 + int(6 * math.cos(math.radians(a))),
                    y + 8 + int(6 * math.sin(math.radians(a))), INK, 1)
    elif key == "cop":
        cv.rect(x, y, w, h, PALE)
        cx, cy = x + w // 2 - 4, y + h // 2
        cv.circle(cx, cy, h // 2 - 2, SEA)
        cv.circle(cx - 3, cy - 3, 3, LAND)
        cv.circle(cx + 4, cy + 3, 4, LAND)
        cv.circle(cx + 5, cy - 5, 2, LAND)
        cv.rect(x + w - 14, y + 3, 3, h - 10, RED)
        cv.circle(x + w - 12, y + 3, 3, RED)
    elif key == "eutalks":
        cv.rect(x, y, w, h, PALE)
        for i, fc in enumerate((SEA, GOLD, RED)):
            cv.rect(x + 5 + i * (w // 3), y + 4, w // 4, 10, fc)
        cv.ellipse(x + w // 2, y + h - 8, w // 2 - 6, 6, LAND)
        cv.circle(x + w // 2 - 8, y + h - 16, 4, FOAM)
        cv.circle(x + w // 2 + 8, y + h - 16, 4, FOAM)
    elif key == "baseball":
        cv.rect(x, y, w, h, PALE)
        cx, cy = x + w // 2, y + h // 2 + 2
        cv.circle(cx, cy, 8, WHITE)
        cv.circle(cx, cy, 8, INK, fill=False)
        cv.line(cx - 6, cy - 5, cx - 2, cy + 5, RED, 1)
        cv.line(cx + 6, cy - 5, cx + 2, cy + 5, RED, 1)
        cv.poly([(cx - 8, y + 3), (cx + 8, y + 3), (cx + 5, y + 8), (cx - 5, y + 8)], RED)
    elif key == "nvidia":
        cv.rect(x, y, w, h, PANEL)
        cx, cy = x + w // 2 - 4, y + h // 2
        for dx in (-8, 0, 8):
            cv.line(cx + dx, y + 4, cx + dx, y + h - 4, INK, 1)
            cv.line(x + 2, cy + dx, x + w - 12, cy + dx, INK, 1)
        cv.rect(cx - 7, cy - 7, 14, 14, INK)
        cv.rect(cx - 4, cy - 4, 8, 8, GOLD)
        cv.circle(x + w - 8, y + 6, 4, RED, fill=False)
        cv.line(x + w - 5, y + 9, x + w - 2, y + 12, RED, 1)
    elif key == "hippo":
        cv.rect(x, y, w, h, PALE)
        cx, cy = x + w // 2, y + h // 2 + 2
        cv.ellipse(cx, cy, 13, 9, SLATE)
        cv.circle(cx - 9, cy - 7, 3, SLATE)
        cv.circle(cx + 9, cy - 7, 3, SLATE)
        cv.circle(cx - 4, cy + 2, 1, INK)
        cv.circle(cx + 4, cy + 2, 1, INK)
        cv.rect(cx - 6, y + 2, 12, 3, INK)
        cv.rect(cx - 6, y + 2, 12, 1, GOLD)
    elif key == "tokyo":
        cv.rect(x, y, w, h, PALE)
        for i in range(5):
            hx = x + 6 + i * ((w - 12) // 4)
            cv.circle(hx, y + h - 8, 4, FOAM)
            cv.rect(hx - 5, y + h - 4, 10, 4, INK)
        cv.rect(x + w // 2 - 10, y + 3, 20, 8, WHITE)
        cv.outline(x + w // 2 - 10, y + 3, 20, 8, INK, 1)
        cv.line(x + w // 2, y + 11, x + w // 2, y + h - 10, INK, 1)
    elif key == "sydney":
        cv.rect(x, y, w, h, PALE)
        cv.poly([(x + 4, y + 5), (x + w - 4, y + 5), (x + w // 2, y + 11)], INK)
        for i in range(3):
            cv.rect(x + 6 + i * ((w - 12) // 2), y + 12, 3, h - 16, INK)
        cv.rect(x + 4, y + h - 5, w - 8, 3, INK)
        cv.rect(x + w - 12, y + 4, 8, 3, RED)
        cv.line(x + w - 8, y + 7, x + w - 4, y + 12, RED, 2)
    elif key == "senegal":
        cv.rect(x, y, w, h, SEA)
        cv.poly([(x + 5, y + h - 9), (x + w - 5, y + h - 9), (x + w - 12, y + h - 3),
                 (x + 12, y + h - 3)], INK)
        cv.line(x + w // 2, y + 4, x + w // 2, y + h - 10, INK, 1)
        cv.poly([(x + w // 2, y + 4), (x + w // 2 + 10, y + h - 12), (x + w // 2, y + h - 12)], WHITE)
        cv.circle(x + 8, y + 7, 4, RED)
        cv.circle(x + 8, y + 7, 2, WHITE)
        cv.line(x, y + h - 2, x + w, y + h - 2, FOAM, 1)
    elif key == "yemen":
        cv.rect(x, y, w, h, PALE)
        for i, bh in enumerate((12, 18, 10, 15)):
            bx = x + 3 + i * (w // 4)
            cv.rect(bx, y + h - bh - 2, w // 5, bh, SLATE)
            cv.rect(bx + 2, y + h - bh + 2, 2, 2, GOLD)
        cv.rect(x + w - 20, y + 3, 18, 10, WHITE)
        cv.outline(x + w - 20, y + 3, 18, 10, INK, 1)
        cv.poly([(x + w - 18, y + 13), (x + w - 14, y + 18), (x + w - 12, y + 13)], WHITE)
        cv.line(x + w - 17, y + 7, x + w - 5, y + 7, INK, 1)
        cv.line(x + w - 17, y + 10, x + w - 8, y + 10, INK, 1)
    elif key == "alaska":
        cv.rect(x, y, w, h, PALE)
        cv.poly([(x + 2, y + h - 2), (x + int(w * 0.3), y + 2),
                 (x + int(w * 0.55), y + h - 2)], WHITE)
        cv.poly([(x + int(w * 0.35), y + h - 2), (x + int(w * 0.65), y + 4),
                 (x + w - 2, y + h - 2)], SLATE)
        cv.poly([(x + int(w * 0.65), y + 4), (x + int(w * 0.72), y + 9),
                 (x + int(w * 0.58), y + 9)], WHITE)
        cv.line(x + w - 14, y + 3, x + w - 14, y + 12, INK, 1)
        cv.poly([(x + w - 14, y + 3), (x + w - 6, y + 6), (x + w - 14, y + 9)], RED)
        cv.rect(x + 4, y + h - 8, 12, 6, WHITE)
        cv.outline(x + 4, y + h - 8, 12, 6, INK, 1)
        cv.line(x + 6, y + h - 5, x + 9, y + h - 2, RED, 1)
        cv.line(x + 9, y + h - 2, x + 14, y + h - 7, RED, 1)
    elif key == "cyber":
        cv.rect(x, y, w, h, PANEL)
        cx, cy = x + w // 2, y + h // 2
        cv.poly([(cx - 9, cy - 8), (cx + 9, cy - 8), (cx + 9, cy + 1),
                 (cx, cy + 10), (cx - 9, cy + 1)], SEA)
        cv.poly([(cx - 6, cy - 5), (cx + 6, cy - 5), (cx + 6, cy + 1),
                 (cx, cy + 7), (cx - 6, cy + 1)], GOLD)
        cv.circle(cx - 3, cy - 1, 1, INK)
        cv.circle(cx + 3, cy - 1, 1, INK)
        cv.line(cx, cy - 1, cx, cy + 3, INK, 1)
    elif key == "paris":
        cv.rect(x, y, w, h, PALE)
        cx = x + w // 2
        cv.line(cx - 5, y + h - 2, cx, y + 3, INK, 2)
        cv.line(cx + 5, y + h - 2, cx, y + 3, INK, 2)
        cv.line(cx - 6, y + h - 2, cx + 6, y + h - 2, INK, 2)
        cv.line(cx - 3, y + h - 8, cx + 3, y + h - 8, INK, 1)
        cv.line(cx - 2, y + h - 14, cx + 2, y + h - 14, INK, 1)
        cv.rect(cx - 1, y + 1, 2, 3, RED)
        cv.rect(x + 3, y + 3, 8, 5, SEA)
        cv.rect(x + w - 11, y + 3, 8, 5, RED)
    elif key == "cricket":
        cv.rect(x, y, w, h, PALE)
        cv.rect(x + 4, y + h - 14, 16, 4, SAND2)
        cv.line(x + 4, y + h - 14, x + w - 8, y + 4, INK, 2)
        cv.rect(x + w - 14, y + 4, 8, 4, INK)
        cv.circle(x + w - 8, y + h - 6, 3, RED)
        for i in range(3):
            cv.line(x + w // 2 - 4 + i * 4, y + h - 12, x + w // 2 - 4 + i * 4, y + h - 3, GOLD, 1)
    elif key == "london":
        cv.rect(x, y, w, h, PALE)
        tx = x + w // 2
        cv.rect(tx - 5, y + 8, 10, h - 10, INK)
        cv.poly([(tx - 6, y + 8), (tx + 6, y + 8), (tx, y + 2)], INK)
        cv.circle(tx, y + 14, 5, WHITE)
        cv.circle(tx, y + 14, 5, INK, fill=False)
        cv.line(tx, y + 14, tx, y + 10, INK, 1)
        cv.line(tx, y + 14, tx + 3, y + 14, INK, 1)
        cv.rect(x + 3, y + h - 6, 8, 4, RED)
        cv.rect(x + w - 11, y + h - 6, 8, 4, SEA)
    else:
        raise AssertionError("unknown scene %r" % key)

# ---------------------------------------------------------------- layout
X0, X1 = 20, 1004
CW = X1 - X0
MASTHEAD = "20 NOVEMBER 2026"

def build():
    worst, map_ratio = check_contrast()
    total, counts = check_counts()
    check_pins()
    cv = CV(W, H, PAPER)
    y = 8

    # ---- kicker
    draw_text(cv, X0, y, "THE WORLD IN ONE PAGE", 2, RED, F4, bold=True)
    r = "ALL TIMES UTC"
    draw_text(cv, X1 - text_w(r, 2, F4), y, r, 2, MUTED, F4, bold=True)
    y += 14
    cv.hline(X0, y, CW, INK, 1)
    y += 4

    # ---- masthead (fit loop: MAST72 first, MAST56 fallback)
    scale = 4
    while scale > 3 and text_w(MASTHEAD, scale, BIG) > CW:
        scale -= 1
    mw = text_w(MASTHEAD, scale, BIG)
    draw_text(cv, X0 + (CW - mw) // 2, y, MASTHEAD, scale, INK, BIG)
    y += _cell(BIG, scale) + 2
    cv.hline(X0, y, CW, INK, 3)
    cv.hline(X0, y + 4, CW, INK, 1)
    y += 8

    # ---- coverage-honesty subline
    sub = "First reported 19 Nov 18:00 UTC - 20 Nov 04:00 UTC. Scheduled items marked SCHEDULED."
    assert text_w(sub, 2, F4) <= CW, "subline too wide"
    draw_text(cv, X0, y, sub, 2, MUTED, F4)
    y += 14

    # ---- reversed count bar (generated from data, never typed)
    bar = "%d STORIES - 20 PICTURES - 33 BRIEFS - %d REGIONS" % (total, len(REGIONS))
    assert total == 53 and len(REGIONS) == 8
    bw = text_w(bar, 2, F5)
    assert bw <= CW
    cv.rect(X0, y, CW, 17, INK)
    draw_text(cv, X0 + (CW - bw) // 2, y + 2, bar, 2, WHITE, F5, bold=True)
    y += 17

    # ---- BY THE CLOCK ruler: 18:00 19 Nov -> 04:00 20 Nov (10 h)
    ry = y
    draw_text(cv, X0, ry, "BY THE CLOCK", 1, RED, F4, bold=True)
    line_x0, line_w = X0 + 110, CW - 110
    line_y = ry + 11
    cv.hline(line_x0, line_y, line_w, INK, 1)
    ticks = [(18, "18:00"), (21, "21:00"), (24, "00:00"), (27, "03:00"), (28, "04:00")]
    for hr, lab in ticks:
        tx = line_x0 + int((hr - 18) / 10.0 * line_w)
        cv.vline(tx, line_y - 3, 7, INK, 1)
        tw = text_w(lab, 1, F4)
        lx = min(max(X0, tx - tw // 2), X1 - tw)
        draw_text(cv, lx, ry, lab, 1, INK, F4)
    events = [(21.0, "ANT CLOSES $97.17", "c"), (25.53, "DECLARATION TEXT OUT", "r"),
              (26.5, "AKVAN BULLETIN", "c")]
    for hr, lab, al in events:
        ex = line_x0 + int((hr - 18) / 10.0 * line_w)
        cv.circle(ex, line_y, 3, RED)
        lw = text_w(lab, 1, F4)
        if al == "r":
            lx = ex - 6 - lw
        elif al == "l":
            lx = ex + 6
        else:
            lx = min(max(line_x0, ex - lw // 2), X1 - lw)
        draw_text(cv, lx, line_y + 3, lab, 1, MUTED, F4)
    y = line_y + 15

    # ---- stat strip: 6 big numbers
    stats = [("53", "STORIES"), ("20", "PICTURES"), ("33", "BRIEFS"),
             ("8", "REGIONS"), ("300,000+", "EVACUATED"),
             ("$2.36BN", "GTA VI SALES (EST.)")]
    assert stats[0][0] == str(total) and stats[4][0] == "300,000+"
    sw = (CW - 5 * 6) // 6
    sy = y
    for i, (num, lab) in enumerate(stats):
        bx = X0 + i * (sw + 6)
        cv.rect(bx, sy, sw, 27, PANEL)
        cv.outline(bx, sy, sw, 27, INK, 1)
        nw = text_w(num, 2, F5)
        assert nw <= sw - 8, "stat number too wide: %s" % num
        draw_text(cv, bx + (sw - nw) // 2, sy + 1, num, 2, INK, F5, bold=True)
        lw = text_w(lab, 1, F4)
        assert lw <= sw - 8, "stat label too wide: %s" % lab
        draw_text(cv, bx + (sw - lw) // 2, sy + 15, lab, 1, MUTED, F4)
    y = sy + 27

    # ---- region bar: text line (from computed counts) + proportional strip
    rline = "REGIONS: " + " - ".join("%s %d" % (REGION_SHORT[r], counts[r]) for r in REGIONS)
    assert text_w(rline, 2, F4) <= CW, "region line too wide"
    draw_text(cv, X0, y, rline, 2, INK, F4)
    y += 14
    bx = X0
    for r in REGIONS:
        segw = int(round(counts[r] / float(total) * CW))
        if counts[r] > 0:
            cv.rect(bx, y, max(segw, 4), 6, REGION_COLOR[r])
        bx += segw
    y += 6

    # ---- leads: 3 equal panels
    lw_ = (CW - 2 * 6) // 3
    ly = y
    for i, ld in enumerate(LEADS):
        px = X0 + i * (lw_ + 6)
        cv.rect(px, ly, lw_, 128, PANEL)
        cv.outline(px, ly, lw_, 128, INK, 1)
        scene(cv, ld["scene"], px + 1, ly + 1, lw_ - 2, 32)
        chip(cv, px + 5, ly + 5, "%d  %s" % (ld["num"], ld["tag"]), 1, WHITE, RED)
        hy = ly + 38
        hl = wrap(ld["head"], lw_ - 16, 3, F5)
        assert len(hl) <= 3, "lead headline >3 lines: %r" % ld["head"]
        hy = draw_lines(cv, px + 8, hy, hl, 3, INK, F5, pitch=28, bold=True)
        dl = wrap(ld["deck"], lw_ - 16, 2, F5)
        assert len(dl) <= 3, "lead deck >3 lines: %r" % ld["deck"]
        dend = draw_lines(cv, px + 8, hy + 2, dl, 2, MUTED, F5, pitch=15)
        assert dend <= ly + 128, "lead deck overflows panel: %r" % ld["head"]
    y = ly + 130

    # ---- tiles: 3 rows, 6 / 6 / 5
    rows = [TILES[0:6], TILES[6:12], TILES[12:17]]
    ty = y
    for ri, row in enumerate(rows):
        n = len(row)
        tw = (CW - (n - 1) * 6) // n
        for ci, t in enumerate(row):
            px = X0 + ci * (tw + 6)
            py = ty + ri * (88 + 4)
            cv.rect(px, py, tw, 88, PANEL)
            cv.outline(px, py, tw, 88, INK, 1)
            scene(cv, t["scene"], px + 1, py + 1, tw - 2, 18)
            cv.rect(px + 4, py + 4, 15, 14, RED)
            num = str(t["num"])
            draw_text(cv, px + 4 + (15 - text_w(num, 1, F4)) // 2, py + 5,
                      num, 1, WHITE, F4, bold=True)
            hl = wrap(t["head"], tw - 10, 2, F4)
            assert len(hl) <= 2, "tile headline >2 lines: %r" % t["head"]
            hy = draw_lines(cv, px + 5, py + 21, hl, 2, INK, F4, pitch=15, bold=True)
            dl = wrap(t["deck"], tw - 10, 2, F4)
            assert len(dl) <= 2, "tile deck >2 lines: %r" % t["deck"]
            draw_lines(cv, px + 5, hy + 2, dl, 2, MUTED, F4, pitch=15)
            twd = text_w(t["tag"], 1, F4)
            draw_text(cv, px + tw - 5 - twd, py + 78, t["tag"], 1, MUTED, F4)
    y = ty + 3 * 88 + 2 * 4 + 2

    # ---- map band: map left (560), key/legend column right (412)
    my = y
    draw_text(cv, X0, my, "WHERE IT HAPPENED", 2, INK, F5, bold=True)
    kr = "PINS = CARDS - DOTS = BRIEFS"
    draw_text(cv, X1 - text_w(kr, 2, F4), my, kr, 2, MUTED, F4, bold=True)
    map_y = my + 15
    map_h = 132
    map_box_x, map_box_w = X0, 560
    mscale = min(map_box_w / (MAP_LON1 - MAP_LON0), map_h / (MAP_LAT1 - MAP_LAT0))
    mw_ = int((MAP_LON1 - MAP_LON0) * mscale)
    mh_ = int((MAP_LAT1 - MAP_LAT0) * mscale)
    mx0 = map_box_x + (map_box_w - mw_) // 2
    my0 = map_y + (map_h - mh_) // 2

    def ll2xy(lon, lat):
        return (mx0 + int((lon - MAP_LON0) * mscale),
                my0 + int((MAP_LAT1 - lat) * mscale))

    cv.rect(map_box_x, map_y, map_box_w, map_h, SEA)
    for poly in LAND_POLYS:
        cv.poly([ll2xy(lon, lat) for lon, lat in poly], LAND)
    # brief dots (gold, ink-ringed) — drawn first so pins sit on top
    for (r, lon, lat, _t) in BRIEFS:
        dx, dy = ll2xy(lon, lat)
        cv.circle(dx, dy, 3, INK)
        cv.circle(dx, dy, 2, GOLD)
    # pins: red numbered discs, fanned where crowded, leader to true spot.
    # Overlap assert: fanned discs (r=7) must not touch -- the assert
    # that would have caught the old 30px fans colliding visually.
    _centres = []
    for it in LEADS + TILES:
        tx, tyy = ll2xy(it["lon"], it["lat"])
        dx, dy = PIN_FAN.get(it["num"], (0, 0))
        _centres.append((it["num"], tx + dx, tyy + dy))
    for i in range(len(_centres)):
        for j in range(i + 1, len(_centres)):
            n1, x1, y1 = _centres[i]
            n2, x2, y2 = _centres[j]
            assert (x1 - x2) ** 2 + (y1 - y2) ** 2 >= 15 * 15, \
                "fanned pins %d and %d overlap: (%d,%d) vs (%d,%d)" % (n1, n2, x1, y1, x2, y2)
    # Fanned disc centres must themselves sit on land (converted back to
    # lon/lat): a fan that drops a disc in the sea is the v2 bug.
    for num, cx, cy in _centres:
        if PIN_FAN.get(num, (0, 0)) != (0, 0):
            dlon = MAP_LON0 + (cx - mx0) / mscale
            dlat = MAP_LAT1 - (cy - my0) / mscale
            assert on_land(dlon, dlat), \
                "fanned pin %d disc sits in the sea: lon %.1f lat %.1f" % (num, dlon, dlat)
    for it in LEADS + TILES:
        tx, tyy = ll2xy(it["lon"], it["lat"])
        dx, dy = PIN_FAN.get(it["num"], (0, 0))
        px, py = tx + dx, tyy + dy
        if (dx, dy) != (0, 0):
            cv.line(px, py, tx, tyy, INK, 1)
            cv.circle(tx, tyy, 2, INK)
        cv.circle(px, py, 7, PINRED)
        cv.circle(px, py, 7, WHITE, fill=False)
        num = str(it["num"])
        draw_text(cv, px - text_w(num, 1, F4) // 2, py - 6, num, 1, WHITE, F4, bold=True)
    # footnote generated from the data (never hand-typed numbers)
    foot = ("PINS 1-%d ARE THE LEADS; PINS %d-%d ARE THE TILES; "
            "DOTS ARE THE %d BRIEFS." % (len(LEADS), len(LEADS) + 1,
                                         len(LEADS) + len(TILES), len(BRIEFS)))
    assert len(LEADS) == 3 and len(TILES) == 17 and len(BRIEFS) == 33
    draw_text(cv, X0, map_y + map_h + 3, foot, 1, MUTED, F4)
    # right column: key + region legend with counts + 4 stat boxes
    rx = X0 + 572
    rw = X1 - rx
    draw_text(cv, rx, my, "MAP KEY", 2, INK, F5, bold=True)
    ky = my + 16
    key_lines = ["RED PINS ARE THE 20 PICTURED STORIES.",
                 "GOLD DOTS ARE THE 33 BRIEFS."]
    for kl in key_lines:
        assert text_w(kl, 2, F4) <= rw, "key line too wide: %s" % kl
        draw_text(cv, rx, ky, kl, 2, MUTED, F4)
        ky += 14
    ky += 2
    for ci in range(0, 8, 2):
        for ri2 in range(2):
            idx = ci + ri2
            if idx >= 8:
                break
            r = REGIONS[idx]
            lx = rx + ri2 * (rw // 2)
            cv.rect(lx, ky, 9, 9, REGION_COLOR[r])
            lab = "%s %d" % (REGION_SHORT[r], counts[r])
            draw_text(cv, lx + 13, ky - 2, lab, 2, INK, F4)
        ky += 13
    ky += 2
    stat4 = [("%d PINS" % (len(LEADS) + len(TILES))),
             ("%d DOTS" % len(BRIEFS)),
             ("%d REGIONS" % len(REGIONS)),
             "CUT 04:00 UTC"]
    bw4 = (rw - 6) // 2
    for i, s4 in enumerate(stat4):
        bx = rx + (i % 2) * (bw4 + 6)
        by = ky + (i // 2) * (18 + 4)
        cv.rect(bx, by, bw4, 18, PANEL)
        cv.outline(bx, by, bw4, 18, INK, 1)
        sw4 = text_w(s4, 2, F4)
        assert sw4 <= bw4 - 8
        draw_text(cv, bx + (bw4 - sw4) // 2, by + 2, s4, 2, INK, F4, bold=True)
    y = max(map_y + map_h + 14, ky + 2 * 18 + 4) + 2

    # ---- briefs: 3 columns x 11 rows, column-major
    draw_text(cv, X0, y, "THE BRIEFS", 2, INK, F5, bold=True)
    cv.hline(X0, y + 15, CW, INK, 1)
    by = y + 17
    colw = (CW - 2 * 6) // 3
    for ci in range(3):
        cx = X0 + ci * (colw + 6)
        for ri2 in range(11):
            bi = ci * 11 + ri2
            if bi >= len(BRIEFS):
                break
            r, lon, lat, txt = BRIEFS[bi]
            num = "%d." % (bi + 1)
            line = num + " " + txt
            assert text_w(line, 2, F4) <= colw, "brief too wide: %r" % line
            draw_text(cv, cx, by + ri2 * 15, num, 2, RED, F4, bold=True)
            draw_text(cv, cx + text_w(num + " ", 2, F4), by + ri2 * 15, txt, 2, INK, F4)
    y = by + 11 * 15 + 2

    # ---- DATE CHECK (red box): stories that are NOT 20 Nov news
    dy = y
    dt = "DATE CHECK - NOT 20 NOVEMBER NEWS"
    cv.outline(X0, dy, CW, 62, RED, 2)
    draw_text(cv, X0 + 6, dy + 3, dt, 2, RED, F5, bold=True)
    for i, dl in enumerate(DATE_CHECK):
        assert text_w(dl, 2, F4) <= CW - 12, "date check line too wide: %r" % dl
        draw_text(cv, X0 + 6, dy + 18 + i * 15, dl, 2, INK, F4)
    y = dy + 62 + 3

    # ---- footer
    foot2 = "FRIDAY 20 NOVEMBER 2026 - %d STORIES - FIRST REPORTED 19 NOV 18:00 UTC TO 20 NOV 04:00 UTC" % total
    assert text_w(foot2, 2, F4) <= CW
    draw_text(cv, X0 + (CW - text_w(foot2, 2, F4)) // 2, y, foot2, 2, MUTED, F4)
    y += 6
    assert y <= 1020, "final layout y=%d > 1020" % y
    print("LAYOUT: final y=%d (limit 1020)" % y)
    return cv

def main():
    outdir = os.environ.get("MAKEFUN_OUTPUT_DIR")
    assert outdir, "MAKEFUN_OUTPUT_DIR not set"
    assert os.path.isdir(outdir), "MAKEFUN_OUTPUT_DIR not a dir: %s" % outdir
    outpath = os.path.join(outdir, "entry.png")
    assert os.path.basename(outpath) == "entry.png"
    cv = build()
    assert cv.w == 1024 and cv.h == 1024
    write_png(outpath, cv.w, cv.h, bytes(cv.buf))
    import hashlib
    data = open(outpath, "rb").read()
    print("WROTE %s %d bytes sha256=%s" % (outpath, len(data),
          hashlib.sha256(data).hexdigest()))
    print("OUTPUT DIR: %s" % sorted(os.listdir(outdir)))

if __name__ == "__main__":
    main()
